INSERT INTO `contentpages` (`conid`, `title`, `dailytitle`, `description`, `photopath`, `photopath2`, `photopath3`, `photopath4`, `photopath5`, `photopath6`, `photopath7`, `photopath8`, `publishdate`, `status`) VALUES
(3, 'Welcome to AJSMR', '', '<div style=\"text-align: justify;\">\r\n<div class=\"WordSection1\">\r\n<h2><span style=\"font-size: large;\"><span style=\"color: rgb(0, 0, 128);\"><b>Welcome to AJSMR</b></span></span></h2>\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\">&nbsp; </div>\r\n<span style=\"color: rgb(128, 128, 128);\">\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><span style=\"font-size: large;\"><b>The American Journal of Science and Medical Research (AJSMR) (ISSN:2377-6196)</b>, a publication of AIRA, is a peer-reviewed online journal with Quarterly Open Access Journal of best quality dedicated to various disciplines of sciences with medical research. The journal&rsquo;s full text is available online at http://ajsmrjournal.com/. The journal allows free access (Open Access) to its contents and permits authors to self-archive final accepted version of the articles on any OAI-compliant institutional / subject-based repository.&nbsp;AJSMR publishes Original Research Articles, Reviews/Mini-Reviews, Opinions &amp; Perspectives, Book Reviews for the Sciences, Short Communications, and Research Notes.</span></div>\r\n</span><span style=\"font-size: large;\"><span style=\"color: rgb(128, 128, 128);\"> </span> </span>\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><span style=\"font-size: large;\"><span style=\"color: rgb(128, 128, 128);\"><br />\r\nThe aim of the Journal is to publish high quality articles and provides an opportunity to share the information among the scientists and researchers. This scientific journal includes a wide range of fields in its discipline to create a platform for the authors to make their contribution towards the journal and the editorial office promises a peer review process for the submitted manuscripts for the quality of publishing.</span></span></div>\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\">&nbsp; </div>\r\n<span style=\"font-size: large;\">\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><b><span style=\"color: rgb(0, 32, 96);\">Abstracting and Indexing Information</span></b></div>\r\n</span>\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><span style=\"font-size: large;\">&nbsp;</span></div>\r\n<span style=\"font-size: large;\"> <b><i><span style=\"color: rgb(0, 112, 192);\">The journal is indexed with, or included in, the following:</span></i></b> </span>\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\">&nbsp;</div>\r\n<span style=\"font-size: large;\">\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><span style=\"color: rgb(128, 128, 128);\">DOAJ, Google Scholar, Index Copernicus, Indian Science Abstracts, NCBI-PubMed Researcher ID, Publons.</span></div>\r\n</span>\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><span style=\"font-size: large;\">&nbsp;</span> </div>\r\n<span style=\"font-size: large;\">\r\n<div style=\"margin-bottom: 0.0001pt; line-height: normal;\"><b><span style=\"color: midnightblue;\">AJSMR publishes in the field of Pharmaceutical, Medical and Biological sciences</span></b></div>\r\n</span>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal;\"><span style=\"font-size: large;\"><span style=\"color: rgb(128, 128, 128);\">Researchers and practitioners are encouraged to submit original, unpublished contributions. The topics of interest include but are not limited to: (Multidisciplinary subjects are especially encouraged.)</span></span></p>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '', '', '', '', '', '', '', '', '0000-00-00', 1);
